// Package contract_test consumes fixtures generated by the Python authority.
package contract_test

import (
	"bytes"
	"context"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"reflect"
	"strings"
	"testing"
	"time"

	"github.com/llcoolkm/rookery/go/core"
)

type vectors struct {
	FormatVersion int `json:"format_version"`
	Hub           []struct {
		Name     string
		Request  core.RPCRequest
		Response core.RPCResponse
		Status   int
	}
	Delivery []struct {
		Name     string
		Message  core.Message
		Envelope core.Envelope
		Text     string
	}
	MCP []struct {
		Name              string
		Request, Response json.RawMessage
	}
	Local []struct {
		Name     string
		Request  core.Command
		Response json.RawMessage
	}
	MCPFrames []struct {
		Name      string
		InputHex  string `json:"input_hex"`
		Repeat    string
		Count     int
		Suffix    string
		Responses []json.RawMessage
	} `json:"mcp_frames"`
	RequestIDs []struct {
		ID      string
		Created *float64
	} `json:"request_ids"`
}

func load(t *testing.T) vectors {
	t.Helper()
	b, err := os.ReadFile("testdata/contract.json")
	if err != nil {
		t.Fatal(err)
	}
	var v vectors
	if err := json.Unmarshal(b, &v); err != nil {
		t.Fatal(err)
	}
	if v.FormatVersion != 1 {
		t.Fatalf("unsupported fixture format: %d", v.FormatVersion)
	}
	return v
}

// Decoding exercises real wire models, including false receipt flags and Unicode
// bodies. It is not a claim that the phase 1 helper implements the protocol.
func TestWireModels(t *testing.T) {
	v := load(t)
	if len(v.Hub) == 0 || len(v.MCP) == 0 || len(v.Local) == 0 || len(v.MCPFrames) == 0 {
		t.Fatal("missing protocol fixtures")
	}
	for _, c := range v.Hub {
		t.Run(c.Name, func(t *testing.T) {
			if c.Request.Op == "" || c.Request.Data == nil {
				t.Fatal("invalid RPC request")
			}
			if c.Response.OK != (c.Status == 200) {
				t.Fatal("HTTP and RPC outcome disagree")
			}
			if c.Response.OK && !json.Valid(c.Response.Result) {
				t.Fatal("missing successful result")
			}
			if !c.Response.OK && c.Response.Error == "" {
				t.Fatal("missing error text")
			}
		})
	}
	for _, c := range v.Delivery {
		t.Run(c.Name, func(t *testing.T) {
			if c.Message.ID != c.Envelope.ID || c.Message.Body != c.Envelope.Body || c.Message.Kind != c.Envelope.Kind {
				t.Fatal("envelope lost message data")
			}
			if c.Message.ReceivedByHost == nil || *c.Message.ReceivedByHost {
				t.Fatal("false receipt flag was lost")
			}
			lines := strings.Split(c.Text, "\n")
			expected := 2
			if c.Message.Kind == core.Ask {
				expected = 3
			}
			if len(lines) != expected {
				t.Fatal("native body forged a line")
			}
			var envelope core.Envelope
			if err := json.Unmarshal([]byte(lines[1]), &envelope); err != nil {
				t.Fatal(err)
			}
			if !reflect.DeepEqual(envelope, c.Envelope) {
				t.Fatal("native text differs from envelope")
			}
		})
	}
	for _, c := range v.Local {
		var data struct {
			RequestID string `json:"_request_id"`
		}
		if err := json.Unmarshal(c.Request.Data, &data); err != nil {
			t.Fatal(err)
		}
		if c.Request.ID != data.RequestID {
			t.Fatal("local durable request identity mismatch")
		}
	}
}

func TestRequestIDVectors(t *testing.T) {
	for _, c := range load(t).RequestIDs {
		got, err := core.RequestCreated(c.ID)
		if err != nil {
			t.Fatal(err)
		}
		if c.Created == nil {
			if got != nil {
				t.Fatal("legacy UUID must not acquire a timestamp")
			}
		} else if got == nil || float64(got.UnixMilli())/1000 != *c.Created {
			t.Fatalf("timestamp mismatch for %s", c.ID)
		}
	}
	now := time.Unix(1800000000, 123000000)
	id, err := core.NewRequestID(now)
	if err != nil {
		t.Fatal(err)
	}
	got, err := core.RequestCreated(id)
	if err != nil || got == nil || !got.Equal(now) {
		t.Fatal("generated UUIDv7 lost timestamp")
	}
}

